bool canJump(int *nums, int numsSize) {
  int rightmost = 0;
  for (int i = 0; i < numsSize; i++) {
    if (i <= rightmost) {
      if (i + nums[i] > rightmost) {
        rightmost = i + nums[i];
      }
      if (rightmost >= numsSize - 1) {
        return true;
      }
    }
  }
  return false;
}

class Solution {
public:
  bool canJump(vector<int> &nums) {
    int n = nums.size();
    int rightmost = 0;
    for (int i = 0; i < n; ++i) {
      if (i <= rightmost) {
        rightmost = max(rightmost, i + nums[i]);
        if (rightmost >= n - 1) {
          return true;
        }
      }
    }
    return false;
  }
};

